import gzip
import hashlib
import json
import signal
from collections import deque
from dataclasses import dataclass, replace
from datetime import datetime
from io import BytesIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml


ROOT = Path(__file__).resolve().parent
SESSIONS_PER_YEAR = 252


@dataclass(frozen=True)
class Model:
    mean_lookback_sessions: int
    sharpe_lookback_sessions: int
    discount: float
    reward_window_observations: int
    seed: int

    def __post_init__(self):
        if min(self.mean_lookback_sessions, self.sharpe_lookback_sessions) < 2:
            raise ValueError("Reward lookbacks must be at least two sessions")
        if not 0 < self.discount <= 1 or self.reward_window_observations < 1:
            raise ValueError("Invalid discount or reward window")


@dataclass(frozen=True)
class Execution:
    signal_lag_sessions: int
    cost_bps: float
    slippage_bps: float

    def __post_init__(self):
        if not isinstance(self.signal_lag_sessions, int) or self.signal_lag_sessions < 1:
            raise ValueError("Signal lag must be a positive integer number of sessions")
        if not (0 <= self.cost_bps and 0 <= self.slippage_bps and self.friction < 1):
            raise ValueError("Invalid cost or slippage")

    @property
    def friction(self):
        return (self.cost_bps + self.slippage_bps) / 10_000


def check_prices(prices, columns, start, end):
    if list(prices.columns) != columns or prices.empty:
        raise ValueError("Price data does not contain every configured ticker and field")
    dates = prices.index
    if dates.has_duplicates or not dates.is_monotonic_increasing or dates.hasnans:
        raise ValueError("Price dates must be unique and sorted")
    if not start <= dates[0] <= start + pd.Timedelta(days=7):
        raise ValueError("Price data is missing the start of the requested range")
    if not end - pd.Timedelta(days=7) <= dates[-1] < end:
        raise ValueError("Price data is missing the end of the requested range")
    bad = ~np.isfinite(prices.to_numpy()) | (prices.to_numpy() <= 0)
    if bad.any():
        date_index, column_index = np.argwhere(bad)[0]
        raise ValueError(f"Invalid {columns[column_index]} on {dates[date_index].date()}")


def load_prices(tickers, start, end, snapshots):
    fields = ("Open", "Close")
    columns = [f"{field}_{ticker}" for field in fields for ticker in tickers]
    ticker_key = hashlib.sha256(",".join(tickers).encode()).hexdigest()[:12]
    snapshot_name = f"adjusted_{start.date()}_{end.date()}_{ticker_key}.csv"
    snapshot = snapshots[snapshot_name]
    raw = gzip.decompress(snapshot["gzip"])
    sha256 = hashlib.sha256(raw).hexdigest()
    if sha256 != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch in {snapshot_name}")

    with BytesIO(raw) as file:
        prefix, _, fetched_at = file.readline().decode("utf-8").strip().partition("=")
        if prefix != "fetched_at" or not fetched_at:
            raise ValueError(f"Missing fetch timestamp in {snapshot_name}")
        datetime.fromisoformat(fetched_at)
        body_start = file.tell()
        frame = pd.read_csv(file, index_col=0, parse_dates=True)
    check_prices(frame, columns, start, end)

    opens, closes = (
        frame[[f"{field}_{ticker}" for ticker in tickers]].set_axis(tickers, axis=1)
        for field in fields
    )

    print(
        "Data source: Yahoo Finance (finance.yahoo.com) daily Open/Close from yfinance "
        f"auto_adjust=True embedded in config under data.snapshots (decompressed sha256 {sha256}); "
        "the script does not call yfinance, FRED or any host and reads no data_cache"
    )
    print(f"Input SHA-256: {hashlib.sha256(raw[body_start:]).hexdigest()}")
    print(f"DATA_SHA256: {sha256}")
    report("MARKET_DATA_SNAPSHOT", {
        "path": "config.yaml",
        "key": "data.snapshots",
        "file": snapshot_name,
        "sha256": sha256,
    })
    return opens, closes, fetched_at


class AdaptiveBandit:
    """Keep discounted and recent Bernoulli counts for each asset identity."""

    def __init__(self, size, model, rng):
        self.discount = model.discount
        self.rng = rng
        self.history = np.zeros((size, 2))
        self.recent = [deque(maxlen=model.reward_window_observations) for _ in range(size)]

    def choose(self, candidates):
        history = self.history[candidates] + 1
        recent_wins = np.array([sum(self.recent[asset]) for asset in candidates])
        recent_count = np.array([len(self.recent[asset]) for asset in candidates])
        long_draw = self.rng.beta(history[:, 0], history[:, 1])
        short_draw = self.rng.beta(recent_wins + 1, recent_count - recent_wins + 1)
        return candidates[np.argmax((long_draw + short_draw) / 2)]

    def observe(self, asset, won):
        self.history[asset] *= self.discount
        self.history[asset] += (int(won), int(not won))
        self.recent[asset].append(int(won))

    def mean_success(self, candidates):
        history = self.history[candidates] + 1
        return history[:, 0] / history.sum(axis=1)


def weekly_targets(closes, groups, start, model, lag):
    returns = closes.pct_change(fill_method=None)
    mean_rewards = returns.rolling(model.mean_lookback_sessions).mean().to_numpy()
    sharpe_window = returns.rolling(model.sharpe_lookback_sessions)
    sharpe_rewards = (sharpe_window.mean() / sharpe_window.std()).to_numpy()

    first_session = closes.index.searchsorted(start)
    first_rows = slice(first_session, None)
    if not (np.isfinite(mean_rewards[first_rows]).all()
            and np.isfinite(sharpe_rewards[first_rows]).all()):
        raise ValueError("Reward windows need enough warmup data and nonzero volatility")

    rng = np.random.default_rng(model.seed)
    selection = AdaptiveBandit(closes.shape[1], model, rng)
    allocation = AdaptiveBandit(closes.shape[1], model, rng)
    pending_feedback = deque()
    targets = {}
    previous_week = None
    for row in range(first_session, len(closes)):
        day = closes.index[row]
        week = day.isocalendar()[:2]
        if week == previous_week:
            continue
        previous_week = week

        # Label a decision at the first weekly signal close after its fill open.
        while pending_feedback and pending_feedback[0][0] <= row:
            _, prior_candidates, prior_pick = pending_feedback.popleft()
            scores = mean_rewards[row]
            for asset, group in zip(prior_candidates, groups):
                selection.observe(asset, scores[asset] == scores[group].max())
            scores = sharpe_rewards[row]
            allocation.observe(prior_pick, scores[prior_pick] == scores[prior_candidates].max())

        candidates = np.array([selection.choose(group) for group in groups])
        picked = allocation.choose(candidates)
        probabilities = allocation.mean_success(candidates)
        weights = np.zeros(closes.shape[1])
        weights[candidates] = probabilities / probabilities.sum()

        fill_row = row + lag
        targets[fill_row - first_session] = weights
        pending_feedback.append((fill_row, candidates, picked))
    return targets


def rebalance(positions, uninvested, open_prices, weights, friction):
    """Size at the reference open and reserve enough for friction on both sides."""
    current_values = positions * open_prices
    opening_value = float(uninvested + current_values.sum())

    def cash_after(changes):
        sells = -changes[changes < 0].sum()
        buys = changes[changes > 0].sum()
        return uninvested + sells * (1 - friction) - buys * (1 + friction)

    # Cash decreases monotonically with the target total. Use its feasible bound.
    lower, upper = 0.0, opening_value
    for _ in range(48):
        middle = (lower + upper) / 2
        if cash_after(middle * weights - current_values) >= 0:
            lower = middle
        else:
            upper = middle

    target_values = lower * weights
    changes = target_values - current_values
    remaining = cash_after(changes)
    if remaining < 0:
        raise ArithmeticError("Rebalance exceeded available cash")
    traded = np.abs(changes)
    n_trades = np.count_nonzero(traded > opening_value * 1e-10)
    return target_values / open_prices, remaining, traded.sum() / opening_value, n_trades


def simulate(opens, closes, targets, friction):
    if not opens.index.equals(closes.index) or not opens.columns.equals(closes.columns):
        raise ValueError("Open and close prices must have the same dates and assets")
    positions = np.zeros(opens.shape[1])
    uninvested = previous_value = 1.0
    net_returns = np.empty(len(opens))
    turnover = np.zeros(len(opens))
    trades = np.zeros(len(opens), dtype=int)
    open_values = opens.to_numpy()
    close_values = closes.to_numpy()
    for row, (open_prices, close_prices) in enumerate(zip(open_values, close_values)):
        if row in targets:
            positions, uninvested, turnover[row], trades[row] = rebalance(
                positions, uninvested, open_prices, targets[row], friction
            )
        closing_value = uninvested + positions @ close_prices
        net_returns[row] = closing_value / previous_value - 1
        previous_value = closing_value

    return pd.DataFrame(
        {"net_return": net_returns, "turnover": turnover, "n_trades": trades}, index=opens.index
    )


def summarize(daily_results, risk_free):
    returns = daily_results["net_return"]
    if len(returns) < 2:
        raise ValueError("Each reporting period needs at least two sessions")
    annual_scale = np.sqrt(SESSIONS_PER_YEAR)
    excess = returns - risk_free.loc[returns.index]
    growth = np.r_[1.0, (1 + returns).cumprod().to_numpy()]
    years = len(returns) / SESSIONS_PER_YEAR
    daily_vol = returns.std(ddof=1)
    excess_vol = excess.std(ddof=1)
    return {
        "cagr": float(growth[-1] ** (1 / years) - 1),
        "ann_vol": float(annual_scale * daily_vol),
        "sharpe": float(annual_scale * returns.mean() / daily_vol) if daily_vol > 0 else None,
        "sharpe_excess": float(annual_scale * excess.mean() / excess_vol) if excess_vol > 0 else None,
        "max_drawdown": float((growth / np.maximum.accumulate(growth) - 1).min()),
        "total_return": float(growth[-1] - 1),
        "turnover": float(daily_results["turnover"].sum() / years),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def report(label, metrics):
    print(f"{label}: {json.dumps(metrics, ensure_ascii=False, allow_nan=False)}")


def main():
    config = yaml.safe_load((ROOT / "config.yaml").read_text(encoding="utf-8"))
    data = config["data"]
    warmup, start, is_end, end = (
        pd.Timestamp(data[key]) for key in ("warmup_start", "start", "is_end", "end_exclusive")
    )
    if not warmup < start < is_end < end:
        raise ValueError("Expected warmup_start < start < is_end < end_exclusive")
    partitions = list(config["groups"].values())
    universe = [ticker for partition in partitions for ticker in partition]
    benchmark, risk_ticker = data["benchmark"], data["risk_free"]
    tickers = [*universe, benchmark, risk_ticker]
    if len(partitions) < 2 or any(len(group) < 2 for group in partitions):
        raise ValueError("Bandit layers need at least two groups and two assets per group")
    if len(tickers) != len(set(tickers)):
        raise ValueError("Each ticker must appear exactly once in the configuration")
    groups = [np.array([universe.index(ticker) for ticker in group]) for group in partitions]

    model = Model(**config["model"])
    execution = Execution(**config["execution"])
    trials = {(model, execution)}
    opens, closes, fetched_at = load_prices(tickers, warmup, end, data["snapshots"])
    sector_opens = opens.loc[start:, universe]
    sector_closes = closes.loc[:, universe]
    risk_free = closes[risk_ticker].pct_change(fill_method=None)
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print("PRICE_ADJUSTMENT: yfinance auto_adjust=True, split- and distribution-adjusted Open/Close")

    print("ROBUSTNESS (IS only)")
    for variant in config["robustness"]:
        variant_model = replace(model, **variant.get("model", {}))
        variant_execution = replace(execution, **variant.get("execution", {}))
        specification = (variant_model, variant_execution)
        if specification in trials:
            raise ValueError(f"Duplicate robustness specification: {variant['name']}")
        targets = weekly_targets(
            sector_closes.loc[:is_end], groups, start, variant_model,
            variant_execution.signal_lag_sessions,
        )
        daily_results = simulate(
            sector_opens.loc[:is_end], sector_closes.loc[start:is_end], targets,
            variant_execution.friction,
        )
        report(variant["name"], summarize(daily_results, risk_free.loc[:is_end]))
        trials.add(specification)

    targets = weekly_targets(sector_closes, groups, start, model, execution.signal_lag_sessions)
    official = simulate(sector_opens, sector_closes.loc[start:], targets, execution.friction)
    benchmark_results = simulate(
        opens.loc[start:, [benchmark]], closes.loc[start:, [benchmark]],
        {min(targets): np.ones(1)}, execution.friction,
    )

    periods = {
        "is": official.index <= is_end,
        "oos": official.index > is_end,
        "full": np.ones(len(official), dtype=bool),
    }
    metrics = {name: summarize(official.loc[mask], risk_free) for name, mask in periods.items()}
    if any(metrics[name]["n_trades"] == 0 for name in ("is", "oos")):
        raise ValueError("The default strategy must record fills in both IS and OOS")
    benchmark_metrics = {
        name: summarize(benchmark_results.loc[mask], risk_free) for name, mask in periods.items()
    }
    for name in periods:
        report(name.upper(), metrics[name])
        report(f"BENCHMARK {benchmark} {name.upper()}", benchmark_metrics[name])

    results = {
        "strategy": config["strategy"],
        "data_range": [str(official.index[0].date()), str(official.index[-1].date())],
        **metrics,
        "benchmark": benchmark_metrics["full"],
    }
    print("BACKTEST_STATUS: 已回测")
    print(f"PARAM_COMBOS_TRIED: {len(trials)}")
    report("RESULTS_JSON", results)


if __name__ == "__main__":
    signal.alarm(14 * 60)
    main()
